            return False

    # Key
    if m.key != n.key:
        return False

    # Left side
    if n.left is None and m.left is not None:
        return False
    if n.left is not None and m.left is None:
        return False
    if n.left is not None and m.left is not None:
        if not compare_trees(n.left, m.left):
            return False

