def treeoutput(root):
  if root != None:
    treeoutput(root.left)
    treeoutput(root.right)
  return root

def insert(root, insert):
  x = root
  y = None
  while x != None:
    y = x
    if (insert.key < x.key):
      x = x.left
    else:
      x = x.right
  insert.parent = y
  if y == None:
    root = insert
  elif insert.key < y.key:
    y.left = insert
  else:
    y.right = insert
  return treeoutput(root)

