def _isCorrect(c, v, m, result):
    n = len(c)

    Result = [0] * (n+1)
    for i in range(n+1):
        Result[i] = [0] * (m+1)

    for i in range(n+1):
        for j in range(m+1):
            Result[i][j] = 0

    for i in range(n-1,-1,-1):
        for j in range(1,m+1):
            if v[i] <= j:
                Result[i][j] = max(c[i] + Result[i+1][j-v[i]],
                                   Result[i+1][j])
            else:
                Result[i][j] = Result[i+1][j]

    return abs(Result[0][m] - result) < 0.01 # Use float comparison - just in case

