from random import randrange

class ListToSort:

    def __init__(self, listInput):
        self._lst = listInput
        self._count = 0

    def Swap(self, x, y):
        self._count += 1
        if x >= len(self._lst) or y >= len(self._lst) or x < 0 or y < 0:
            raise IndexError
        tmp = self._lst[x]
        self._lst[x] = self._lst[y]
        self._lst[y] = tmp

    def Larger(self, x, y):
        self._count += 1
        if x >= len(self._lst) or y >= len(self._lst) or x < 0 or y < 0:
            raise IndexError
        return self._lst[x] > self._lst[y]

    def Smaller(self, x, y):
        self._count += 1
