        n.parent = y
        if y is None:
            root2 = n
        elif n.key < y.key:
            y.left = n
        else:
            y.right = n

        if deleted:
            delete = n

    if toDelete is None:
        toDelete = root1
        delete = root2

    # Node to delete - root 2

    y = None  # y: node to delete (after swap)

    if delete.left is None or delete.right is None:
        y = delete
    else:
        y = delete.right
        while y.left != None:
            y = y.left

    x = None  # non-None child of y
    if y.left is not None:
        x = y.left
    else:
        x = y.right

    # now delete y
