    root1 = None
    root2 = None

    number = get_random_number_nodes()

    toDelete = None
    delete = None

    for i in range(number + 1):
        key = get_random_key()
        deleted = False

        # Root 1
        n = Node()
        n.key = key

        x = root1
        y = None
        while x is not None:
