import random


class Node:
    def __init__(self):
        self.key = None
        self.parent = None
        self.left = None
        self.right = None


def get_random_key():
    return random.randrange(-1000000, 1000001, 1)


def get_random_number_nodes():
    return random.randrange(0, 21, 1)


def compare_trees(m, n):
    # None check
    if n is None and m is None:
        return True
    if n is not None and m is None:
        return False
    if n is None and m is not None:
        return False

    # Root
    if n.parent is None and m.parent is not None:
        return False
    if n.parent is not None and m.parent is None:
        return False
    if n.parent is not None and m.parent is not None:
        if n.parent.key != m.parent.key:
            return False

    # Key
    if m.key != n.key:
        return False

    # Left side
    if n.left is None and m.left is not None:
        return False
    if n.left is not None and m.left is None:
        return False
    if n.left is not None and m.left is not None:
        if not compare_trees(n.left, m.left):
            return False

    # Right side
    if n.right is None and m.right is not None:
        return False
    if n.right is not None and m.right is None:
        return False
    if n.right is not None and m.right is not None:
        if not compare_trees(n.right, m.right):
            return False

    # Correct parents
    if n.right is not None:
        if n.right.parent is not n:
            return False

    if n.left is not None:
        if n.left.parent is not n:
            return False

    if m.right is not None:
        if m.right.parent is not m:
            return False

    if m.left is not None:
        if m.left.parent is not m:
            return False

    # All passed
    return True


# Return: (Root1, insert, Root2)
def get_random():
    root1 = None
    root2 = None

    number = get_random_number_nodes()

    toDelete = None
    delete = None

    for i in range(number + 1):
        key = get_random_key()
        deleted = False

        # Root 1
        n = Node()
        n.key = key

        x = root1
        y = None
        while x is not None:
            y = x
            if n.key < x.key:
                x = x.left
            else:
                x = x.right

        n.parent = y
        if y is None:
            root1 = n
        elif n.key < y.key:
            y.left = n
        else:
            y.right = n

        # Maybe this will be deleted?
        if (get_random_number_nodes() < 4):
            deleted = True
            toDelete = n

        # Root 2
        n = Node()
        n.key = key

        x = root2
        y = None
        while x is not None:
            y = x
            if n.key < x.key:
                x = x.left
            else:
                x = x.right

        n.parent = y
        if y is None:
            root2 = n
        elif n.key < y.key:
            y.left = n
        else:
            y.right = n

        if deleted:
            delete = n

    if toDelete is None:
        toDelete = root1
        delete = root2

    # Node to delete - root 2

    y = None  # y: node to delete (after swap)

    if delete.left is None or delete.right is None:
        y = delete
    else:
        y = delete.right
        while y.left != None:
            y = y.left

    x = None  # non-None child of y
    if y.left is not None:
        x = y.left
    else:
        x = y.right

    # now delete y
    if x is not None:
        x.parent = y.parent
    if y.parent is None:
        root2 = x
    else:
        if y is y.parent.left:
            y.parent.left = x
        else:
            y.parent.right = x

    # Copy data
    if y is not delete:
        delete.key = y.key

    return root1, toDelete, root2

